import{_ as e,c as a,o,j as r,Y as s,t as n}from"./chunks/framework.D-NV0Bun.js";const b=JSON.parse('{"title":"dd | x-cmd man (man1) | convert and copy a file","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | dd - convert and copy a file","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"dd | x-cmd man (man1) | convert and copy a file"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | dd - convert and copy a file"}]]},"headers":[],"params":{"isMan":true,"man":"dd","category":"man1","desc":"convert and copy a file"},"relativePath":"man1/dd.md","filePath":"man1/[man].md"}'),i={name:"man1/dd.md"},l={class:"visually-hidden"};function c(d,t,p,u,h,m){return o(),a("div",null,[r("h1",l,n(d.$params.man),1),t[0]||(t[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>dd - convert and copy a file</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>dd</strong> [<em>OPERAND</em>]... <br> <strong>dd</strong> <em>OPTION</em></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Copy a file, converting and formatting according to the operands.</p><dl><dt>bs=BYTES</dt><dd>read and write up to BYTES bytes at a time (default: 512); overrides ibs and obs</dd><dt>cbs=BYTES</dt><dd>convert BYTES bytes at a time</dd><dt>conv=CONVS</dt><dd>convert the file as per the comma separated symbol list</dd><dt>count=N</dt><dd>copy only N input blocks</dd><dt>ibs=BYTES</dt><dd>read up to BYTES bytes at a time (default: 512)</dd><dt>if=FILE</dt><dd>read from FILE instead of stdin</dd><dt>iflag=FLAGS</dt><dd>read as per the comma separated symbol list</dd><dt>obs=BYTES</dt><dd>write BYTES bytes at a time (default: 512)</dd><dt>of=FILE</dt><dd>write to FILE instead of stdout</dd><dt>oflag=FLAGS</dt><dd>write as per the comma separated symbol list</dd><dt>seek=N</dt><dd>(or oseek=N) skip N obs-sized output blocks</dd><dt>skip=N</dt><dd>(or iseek=N) skip N ibs-sized input blocks</dd><dt>status=LEVEL</dt><dd>The LEVEL of information to print to stderr; &#39;none&#39; suppresses everything but error messages, &#39;noxfer&#39; suppresses the final transfer statistics, &#39;progress&#39; shows periodic transfer statistics</dd></dl><p>N and BYTES may be followed by the following multiplicative suffixes: c=1, w=2, b=512, kB=1000, K=1024, MB=1000*1000, M=1024*1024, xM=M, GB=1000*1000*1000, G=1024*1024*1024, and so on for T, P, E, Z, Y, R, Q. Binary prefixes can be used, too: KiB=K, MiB=M, and so on. If N ends in &#39;B&#39;, it counts bytes not blocks.</p><p>Each CONV symbol may be:</p><dl><dt>ascii</dt><dd>from EBCDIC to ASCII</dd><dt>ebcdic</dt><dd>from ASCII to EBCDIC</dd><dt>ibm</dt><dd>from ASCII to alternate EBCDIC</dd><dt>block</dt><dd>pad newline-terminated records with spaces to cbs-size</dd><dt>unblock</dt><dd>replace trailing spaces in cbs-size records with newline</dd><dt>lcase</dt><dd>change upper case to lower case</dd><dt>ucase</dt><dd>change lower case to upper case</dd><dt>sparse</dt><dd>try to seek rather than write all-NUL output blocks</dd><dt>swab</dt><dd>swap every pair of input bytes</dd><dt>sync</dt><dd>pad every input block with NULs to ibs-size; when used with block or unblock, pad with spaces rather than NULs</dd><dt>excl</dt><dd>fail if the output file already exists</dd><dt>nocreat</dt><dd>do not create the output file</dd><dt>notrunc</dt><dd>do not truncate the output file</dd><dt>noerror</dt><dd>continue after read errors</dd><dt>fdatasync</dt><dd>physically write output file data before finishing</dd><dt>fsync</dt><dd>likewise, but also write metadata</dd></dl><p>Each FLAG symbol may be:</p><dl><dt>append</dt><dd>append mode (makes sense only for output; conv=notrunc suggested)</dd><dt>direct</dt><dd>use direct I/O for data</dd><dt>directory</dt><dd>fail unless a directory</dd><dt>dsync</dt><dd>use synchronized I/O for data</dd><dt>sync</dt><dd>likewise, but also for metadata</dd><dt>fullblock</dt><dd>accumulate full blocks of input (iflag only)</dd><dt>nonblock</dt><dd>use non-blocking I/O</dd><dt>noatime</dt><dd>do not update access time</dd><dt>nocache</dt><dd>Request to drop cache. See also oflag=sync</dd><dt>noctty</dt><dd>do not assign controlling terminal from file</dd><dt>nofollow</dt><dd>do not follow symlinks</dd></dl><p>Sending a USR1 signal to a running &#39;dd&#39; process makes it print I/O statistics to standard error and then resume copying.</p><p>Options are:</p><dl><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Paul Rubin, David MacKenzie, and Stuart Kemp.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/dd%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/dd\\</a>&gt; <br> or available locally via: info &#39;(coreutils) dd invocation&#39;</p>',23))])}const g=e(i,[["render",c]]);export{b as __pageData,g as default};
